    internal static Bitmap Create(string glyph, Color color)
    {
        var image = new Bitmap(64, 64);
        using var graphics = Graphics.FromImage(image);
        graphics.ScaleTransform(64 / 24f, 64 / 24f);
        graphics.SmoothingMode = SmoothingMode.AntiAlias;
        using var brush = new SolidBrush(color);
        using var path = new GraphicsPath(FillMode.Winding);
        var tokens = System.Text.RegularExpressions.Regex.Matches(CommandPaths[glyph], @"[A-Z]|-?(?:\d+(?:\.\d+)?|\.\d+)");
        var point = PointF.Empty;
        int index = 0;
        float Number() => float.Parse(tokens[index++].Value, System.Globalization.CultureInfo.InvariantCulture);
        PointF Point() => new(Number(), Number());
        while (index < tokens.Count)
        {
            string command = tokens[index++].Value;
            switch (command)
            {
                case "M": path.StartFigure(); point = Point(); break;
                case "L":
                    do { var next = Point(); path.AddLine(point, next); point = next; }
                    while (index < tokens.Count && !char.IsLetter(tokens[index].Value[0]));
                    break;
                case "H": { var next = new PointF(Number(), point.Y); path.AddLine(point, next); point = next; break; }
                case "V": { var next = new PointF(point.X, Number()); path.AddLine(point, next); point = next; break; }
                case "C": { var first = Point(); var second = Point(); var next = Point(); path.AddBezier(point, first, second, next); point = next; break; }
                case "Z": path.CloseFigure(); break;
                default: throw new InvalidDataException("Unsupported Fluent path command " + command);
            }
        }
        graphics.FillPath(brush, path);
        return image;
    }
