        current = next;
        next = new PointF(14.8118f, 13.2557f);
        path.AddBezier(current, new PointF(13.8835f, 13.9774f), new PointF(14.2857f, 13.5188f), next);
        current = next;
        next = new PointF(19.6827f, 10.8202f);
        path.AddLine(current, next);
        current = next;
        next = new PointF(20.0076f, 8.81831f);
        path.AddBezier(current, new PointF(20.4458f, 10.4387f), new PointF(20.6109f, 9.42161f), next);
        current = next;
        path.CloseFigure();
        return path;
    }
}
